// Kotlin/JVM bindings for ecitygml. src/main is generated by Diplomat (`mise run generate-bindings`); this build
// file, src/test and src/examples are hand-written. The native library is loaded with JNA.

plugins {
    kotlin("jvm") version "2.4.20"
}

group = "space.envis"
version = "0.0.1-SNAPSHOT"

repositories {
    mavenCentral()
}

dependencies {
    implementation("net.java.dev.jna:jna:5.19.1")
    testImplementation(kotlin("test"))
    testImplementation(platform("org.junit:junit-bom:6.1.3"))
    testImplementation("org.junit.jupiter:junit-jupiter")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

kotlin {
    jvmToolchain(21)
}

// Examples (src/examples), compiled against the bindings; run with `gradle run01ReadCityModel --args="model.gml"` etc.
val examples: SourceSet by sourceSets.creating {
    compileClasspath += sourceSets.main.get().output
    runtimeClasspath += sourceSets.main.get().output
}
configurations[examples.implementationConfigurationName].extendsFrom(configurations.implementation.get())
configurations[examples.runtimeOnlyConfigurationName].extendsFrom(configurations.runtimeOnly.get())
// The tests run the examples too.
sourceSets.test {
    compileClasspath += examples.output
    runtimeClasspath += examples.output
}

// Debug build of crates/ecitygml-ffi (`cargo build -p ecitygml-ffi`), unless overridden with -PnativeLibraryDir=...
val nativeLibraryDir = providers.gradleProperty("nativeLibraryDir")
    .orElse(layout.projectDirectory.dir("../../../../target/debug").asFile.absolutePath)

tasks.test {
    useJUnitPlatform()
    systemProperty("jna.library.path", nativeLibraryDir.get())
    systemProperty("ecitygml.fixtures", layout.projectDirectory.dir("../../../../tests/fixtures").asFile.absolutePath)
    // Expected outputs of the examples, shared by all languages.
    systemProperty("ecitygml.examples.expected", layout.projectDirectory.dir("../../tests/examples/expected").asFile.absolutePath)
    // Rerun the tests when the fixtures or expected outputs change (Gradle doesn't see files read at runtime).
    inputs.dir(layout.projectDirectory.dir("../../../../tests/fixtures"))
    inputs.dir(layout.projectDirectory.dir("../../tests/examples/expected"))
}

for ((name, mainClass) in listOf(
    "run01ReadCityModel" to "ReadCityModelKt",
    "run02ListFeatures" to "ListFeaturesKt",
    "run03BuildingReport" to "BuildingReportKt",
    "run04RoadNetwork" to "RoadNetworkKt",
    "run05MeasureGeometry" to "MeasureGeometryKt",
    "run06ExportObj" to "ExportObjKt",
    "run07Convert" to "ConvertKt",
)) {
    tasks.register<JavaExec>(name) {
        group = "examples"
        classpath = examples.runtimeClasspath
        this.mainClass.set("space.envis.ecitygml.examples.$mainClass")
        systemProperty("jna.library.path", nativeLibraryDir.get())
    }
}
